L25_1 = "USER_ADMIN_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "뭐라도 구해보려고 여기까지 왔는데, 그게 사람 목숨이라면 마다할 이유는 없지."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "助けるためにここまで来たのだ。それが人の命ならば、躊躇する理由はない。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "We came here to save something. So there's no reason to turn down a chance to save people's lives."
L24_1.m_Talk_ENG = L25_1
L25_1 = "千里迢迢來到這裡，竟然有機會拯救人命為何要拒絕呢。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "都千里迢迢来到这里了，能救一个就救一个。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "We came here to save something. So there's no reason to turn down a chance to save people's lives."
L24_1.m_Talk_DEU = L25_1
L25_1 = "We came here to save something. So there's no reason to turn down a chance to save people's lives."
