L49_1.m_Pos = "C"
L50_1 = "자신의 힘으로 열 수 없는 자물쇠를 걸어 두다니. 대적자도 아니면서 제법 철저하시네요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "自分の力では開けられない鍵をかけておくとは。敵対者でもないくせに、なかなか徹底していますね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "A lock that even he can't open himself. Rather thorough from someone who is not even an Antagonist."
L49_1.m_Talk_ENG = L50_1
L50_1 = "竟然上了連自己也打不開的鎖。又不是對敵者，做得還真是徹底。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "一把连他自己也打不开的锁。甚至连敌对者也不是，做得还真是彻底。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "A lock that even he can't open himself. Rather thorough from someone who is not even an Antagonist."
L49_1.m_Talk_DEU = L50_1
