L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "하지만 곧, 열쇠가 직접 제 발로 여기 나타나 마지막 봉인을 열고 대미를 장식하겠죠."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "でも、もうすぐ鍵が自らの足でここに現れ、最後の封印を解き終わりを迎えるでしょう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "But soon, the key to the lock will enter voluntarily to build up the grand finale."
L50_1.m_Talk_ENG = L51_1
L51_1 = "但不久之後，鑰匙會自己走上門來，打開最後的封印，造就一個完美的結局。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "但不久之后，钥匙就会自己走上门来，打开最后的封印，造就一个完美的结局。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "But soon, the key to the lock will enter voluntarily to build up the grand finale."
L50_1.m_Talk_DEU = L51_1
L51_1 = "But soon, the key to the lock will enter voluntarily to build up the grand finale."
