L13_1.m_CutScenStrID = "SWANSONG_ACT4_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "<color=#ffd34c>현재 눈보라 현상을 동반한 고위 침식파가 전세계를 뒤덮고 있습니다.</color>"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "<color=#ffd34c>現在、吹雪を伴う高位の侵食波が全世界を覆いつくしています。</color>"
L13_1.m_Talk_JPN = L14_1
L14_1 = "<color=#ffd34c>The high-grade Corruption ray accompanied by the blizzard is currently covering the world.</color>"
L13_1.m_Talk_ENG = L14_1
L14_1 = "<color=#ffd34c>目前，一股伴有暴風雪的高強度侵蝕波正在席捲全世界。</color>"
L13_1.m_Talk_TWN = L14_1
L14_1 = "<color=#ffd34c>目前，一股伴有暴风雪的高强度侵蚀波正在覆盖全球。</color>"
L13_1.m_Talk_SCN = L14_1
L14_1 = "<color=#ffd34c>The high-grade Corruption ray accompanied by the blizzard is currently covering the world.</color>"
L13_1.m_Talk_DEU = L14_1
L14_1 = "<color=#ffd34c>The high-grade Corruption ray accompanied by the blizzard is currently covering the world.</color>"
L13_1.m_Talk_FRA = L14_1
