L15_1 = "SWANSONG_ACT4_INTERLUDE1@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 6800401
L14_1.m_CutScenStrID = "SWANSONG_ACT4_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "<color=#ffd34c>시민 여러분께서는 절대 눈보라에 노출되지 마시고, 안전한 실내장소로 대피하여 재난방송을 청취해주시기 바랍니다.</color>"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "<color=#ffd34c>市民の皆様は決して吹雪の中に出ず、室内の安全な場所に退避し、テレビ・ラジオをつけてください。</color>"
L14_1.m_Talk_JPN = L15_1
L15_1 = "<color=#ffd34c>Citizens are asked to not be exposed to the snow, evacuate to a safe place indoors, and listen to the disaster broadcast.</color>"
L14_1.m_Talk_ENG = L15_1
L15_1 = "<color=#ffd34c>各位市民千萬不要暴露在暴風雪中，請在室內躲避並收聽災害廣播。</color>"
L14_1.m_Talk_TWN = L15_1
L15_1 = "<color=#ffd34c>各位市民，请务必不要暴露在暴风雪中，请前往室内躲避并收听本灾害广播。</color>"
L14_1.m_Talk_SCN = L15_1
L15_1 = "<color=#ffd34c>Citizens are asked to not be exposed to the snow, evacuate to a safe place indoors, and listen to the disaster broadcast.</color>"
L14_1.m_Talk_DEU = L15_1
L15_1 = "<color=#ffd34c>Citizens are asked to not be exposed to the snow, evacuate to a safe place indoors, and listen to the disaster broadcast.</color>"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
