L15_1.m_CutScenStrID = "SWANSONG_ACT4_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "<color=#ffd34c>안내된 지침은 재난경보 해제까지 유효합니다.</color>"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "<color=#ffd34c>ご案内している行動指針は災難警報が解除されるまで有効です。</color>"
L15_1.m_Talk_JPN = L16_1
L16_1 = "<color=#ffd34c>The broadcast guidelines will remain in effect until the disaster alert is lifted.</color>"
