L43_1 = "USER_ADMIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "만약 일이 잘못되어가고 있다고 느꼈을 땐, 날 믿고 하늘을 올려다보지 말게."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "もし何か間違っていると感じた時は、私を信じて空を見上げないようにしてくれ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "If you feel that things are going wrong, trust me and don't look up into the sky."
L42_1.m_Talk_ENG = L43_1
L43_1 = "當你覺得事情不對勁，相信我，不要抬頭。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "当你觉得事情不对劲时，请相信我，不要抬头看天空。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "If you feel that things are going wrong, trust me and don't look up into the sky."
L42_1.m_Talk_DEU = L43_1
L43_1 = "If you feel that things are going wrong, trust me and don't look up into the sky."
L42_1.m_Talk_FRA = L43_1
