L43_1.m_CharStrID = L44_1
L44_1 = "두 사람도 미나 양 말이라면 따를 테니 말해두는 걸세."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "二人もミナ君の話なら従うはずだから、言っておく。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I'm telling you since the other two will follow whatever you say."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我和你說這些是因為另外兩個人都會聽從你的話。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "这些我只和你说，因为另外两个人都会听从你的话。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "I'm telling you since the other two will follow whatever you say."
L43_1.m_Talk_DEU = L44_1
