L44_1 = "USER_ADMIN_NULL_MIRROR"
L43_1.m_CharStrID = L44_1
L44_1 = "멈춘 시간에 갇혀 만 년이 넘도록 침묵하는 경우도 있었지만, 적어도 나의 세 가지 가능성은 같은 대답을 해줬군."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "止まった時間に閉じ込められて一万年以上沈黙しているときもあったが、少なくとも私の三つの可能性は同じ答えを出してくれた。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "There was a version of you that kept your silence for ten thousand years in frozen time. But at least my three possibilities gave me the same answer."
L43_1.m_Talk_ENG = L44_1
L44_1 = "也可能會被困在永恆的時間裡沉默千萬年，但至少我的三種可能性給出了相同的答案。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "有一种可能性里的你被困在永恒的时间里沉默了成千上万年，但至少这三种可能性给出了相同的答案。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "There was a version of you that kept your silence for ten thousand years in frozen time. But at least my three possibilities gave me the same answer."
L43_1.m_Talk_DEU = L44_1
L44_1 = "There was a version of you that kept your silence for ten thousand years in frozen time. But at least my three possibilities gave me the same answer."
