L1_1.m_fTalkTime = 0.03
L2_1 = "でもそれはあなたが経験するであろう可能性の一つに過ぎません。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "But that was merely one of the possibilities that you could have experienced."
L1_1.m_Talk_ENG = L2_1
L2_1 = "但無論如何，這只是你會遇到的可能性之一。"
L1_1.m_Talk_TWN = L2_1
