L3_1 = "UNIT_PRIDE"
L2_1.m_Face = L3_1
L3_1 = "SWAN_SIX_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "제아무리 당신이라도 실제로 그런 일을 겪었다면 미쳐버렸겠지만, 지금은 멀쩡하잖아요?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "さすがのあなたでも実際にそんな経験をしたら精神が崩壊してしまうかもしれませんが、今は平気でしょう？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Even you would have gone insane if you had gone through that. But look at you now. You're just fine."
L2_1.m_Talk_ENG = L3_1
L3_1 = "如果發生在你身上，你一定會瘋掉吧。但你現在沒事不是嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "如果真的发生在你身上，你一定会疯掉吧。但你现在不是好好的吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Even you would have gone insane if you had gone through that. But look at you now. You're just fine."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Even you would have gone insane if you had gone through that. But look at you now. You're just fine."
L2_1.m_Talk_FRA = L3_1
