L5_1 = "USER_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "클리파 차원을 이런 식으로 이용하는 건, 카운터가 아니라 마왕의 권능에 가까워보이는데."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "クリファ次元をこんな風に利用するのは、カウンターではなく魔王の権能に近いように見えるが。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Manipulating the Qlipha Dimension like this seems closer to the powers of a Demon Lord than a Counter."
L4_1.m_Talk_ENG = L5_1
L5_1 = "以這種方式使用逆卡巴拉次元似乎更像是魔王的權能，而不是制裁者。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "以这种方式使用逆卡巴拉次元似乎更像是魔王的权能，而不是制裁者。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Manipulating the Qlipha Dimension like this seems closer to the powers of a Demon Lord than a Counter."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Manipulating the Qlipha Dimension like this seems closer to the powers of a Demon Lord than a Counter."
L4_1.m_Talk_FRA = L5_1
