L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "…맞아요. 타기리온과 계약해서 힘을 빌렸죠."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "……そうです。タギリオンと契約して力を借りました。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "...You're right. I made a deal with Thagirion to borrow her strength."
L5_1.m_Talk_ENG = L6_1
L6_1 = "……沒錯，我和塔基里翁簽訂了契約，借用了她的力量。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "……没错，我和塔基里翁签订了契约，借用了她的力量。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "...You're right. I made a deal with Thagirion to borrow her strength."
L5_1.m_Talk_DEU = L6_1
L6_1 = "...You're right. I made a deal with Thagirion to borrow her strength."
